entries[40767] = { ["name"] = "Sonic Booster", ["text"] = "Binds when equipped\nTrinket\n+81 Stamina\nRequires Engineering (390)\nEquip: The noise made from melee combat sometimes causes Sonic Awareness, increasing your attack power by 498 for 10 sec. This effect can only occur once every minute. (Proc chance: 35%, 50s cooldown)\nSell Price:" }
entries[40768] = { ["name"] = "MOLL-E", ["text"] = "Binds when used\nToy\nRequires Engineering (425)\nUse: Creates a portable mailbox for 10 min. MOLL-E is not destroyed after use. (1 Hour Cooldown)\n\"Mobile Oversized Letter and Literary Extractor\"" }
entries[40769] = { ["name"] = "Scrapbot Construction Kit", ["text"] = "Requires Engineering (425)\nUse: Creates a mechanical Scrapbot that repairs equipment and buys nearly anything. The scrapbot leaves after 5 min. (15 Min Cooldown)\nSell Price:" }
entries[40771] = { ["name"] = "Cobalt Frag Bomb", ["text"] = "Requires Engineering (330)\nUse: Inflicts ( 75 * 10) to ( 100 * 10) Fire damage and incapacitates targets for 3 sec in a 3 yard radius. Any damage will break the effect. (1 Min Cooldown)\nSell Price:" }
entries[40772] = { ["name"] = "Gnomish Army Knife", ["text"] = "Use: An engineer with at least 350 skill can overload the knife's battery and attempt to shock a dead ally back to life. Cannot be used in combat. (30 Min Cooldown)\n+10 Mining\n+10 Herbalism\n+10 Skinning\n\"Includes Gyromatic Micro-Adjustor, Arclight Spanner, Nose Picker, Blacksmithing Hammer, Back Scratcher, and Whirly Thing.\"\nSell Price:" }
