entries[40775] = { ["name"] = "Winged Steed of the Ebon Blade", ["text"] = "Binds when picked up\nUnique\nMount\nClasses: Death Knight\nRequires Level 60\nRequires Expert Riding\nUse: Teaches you how to summon this mount. This is a flying mount.\nSummons and dismisses your Winged Steed of the Ebon Blade. This is a flying mount." }
entries[40776] = { ["name"] = "Personal Electromagnetic Pulse Generator", ["text"] = "Requires Engineering (375)\nUse: Permanently attaches a high-powered device to your belt, allowing you to confuse nearby mechanicals. Only a skilled engineer can activate the modified belt.\n\nCan only be attached to your own belt, and doing so causes the belt to become soulbound.\nSell Price:" }
entries[40777] = { ["name"] = "Polar Bear Harness", ["text"] = "Binds when picked up\nMount\nRequires Level 60\nRequires Riding (150)\nUse: Teaches you how to summon this mount." }
