entries[40898] = { ["name"] = "Savage Gladiator's Ornamented Chestguard", ["text"] = "Binds when picked up\nChest Plate\n2265 Armor\n+110 Stamina\n+62 Intellect\n+ 36 Critical Strike\n+ 51 PvP Resilience\n\nRed Socket\nYellow Socket\nSocket Bonus: + 6 PvP Resilience\n\nDurability 135 / 135\nClasses: Paladin\nRequires Level 80\n\nGladiator's Redemption (0/5)\nGladiator's Ornamented Chestguard\nGladiator's Ornamented Gloves\nGladiator's Ornamented Headcover\nGladiator's Ornamented Legplates\nGladiator's Ornamented Spaulders\n(2) Set : +100 PvP Resilience.\n(2) Set : Increases Intellect by 25.\n(4) Set : Increases the damage and healing of your Holy Shock spell by 10%.\n(4) Set : Increases Intellect by 75.\nSell Price:" }
entries[40899] = { ["name"] = "Glyph of Omens", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile you are not in an Eclipse, the following abilities now grant 10 Solar or Lunar Energy: Entangling Roots, Cyclone, Faerie Fire, Faerie Swarm, Mass Entanglement, Typhoon, Disorienting Roar, Ursol's Vortex, and Mighty Bash.\nSell Price:" }
entries[40900] = { ["name"] = "Glyph of the Stag", ["text"] = "Minor Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Travel Form can now be used as a mount by party members. This glyph is disabled while Glyph of the Cheetah is active.\nSell Price:" }
entries[40901] = { ["name"] = "Glyph of Shred", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile Berserk or Tiger's Fury is active, Shred has no positional requirement.\nSell Price:" }
entries[40902] = { ["name"] = "Glyph of Prowl", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the movement penalty of Prowl by 100%.\nSell Price:" }
entries[40903] = { ["name"] = "Glyph of Pounce", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the range of your Pounce by 8 yards.\nSell Price:" }
