entries[40909] = { ["name"] = "Glyph of Rebirth", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nPlayers resurrected by Rebirth are returned to life with 100% health.\nSell Price:" }
