entries[40913] = { ["name"] = "Glyph of Rejuvenation", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen you have Rejuvenation active on three or more targets, the cast time of your Nourish spell is reduced by 30%.\nSell Price:" }
entries[40914] = { ["name"] = "Glyph of Healing Touch", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhen you cast Healing Touch, the cooldown on your Nature's Swiftness is reduced by 3 sec.\nSell Price:" }
entries[40915] = { ["name"] = "Glyph of Efflorescence", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nThe Efflorescence effect is now caused by your Wild Mushroom instead of by Swiftmend, and lasts as long as the Wild Mushroom is active. Additionally, increases the healing done by Swiftmend by 20%.\nSell Price:" }
entries[40916] = { ["name"] = "Glyph of Guided Stars", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Starfall only hits targets affected by your Moonfire or Sunfire.\nSell Price:" }
entries[40917] = { ["name"] = "Lord-Commander's Nullifier", ["text"] = "Quest Item\nUnique\nUse: Channel at Grand Admiral Westwind once he's invoked his Protection Sphere to bring it down. Range is 30 yards. (5 Sec Cooldown)" }
