entries[40920] = { ["name"] = "Glyph of Hurricane", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Hurricane and Astral Storm abilities now also slow the movement speed of their victims by 50%.\nSell Price:" }
