entries[40922] = { ["name"] = "Glyph of Nature's Grasp", ["text"] = "Major Glyph\nClasses: Druid\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the cooldown of Nature's Grasp by 45 sec.\nSell Price:" }
