entries[41091] = { ["name"] = "Hand-Mounted Pyro Rocket", ["text"] = "Requires Engineering (375)\nUse: Permanently attaches a hand-mounted pyro rocket launcher to your gloves, allowing a skilled engineer to deal ( 106 * 10) to ( 128 * 10) Fire damage to an enemy at long range. The rocket can only be fired once every 45 sec.\n\nCan only be used on the engineer's gloves, and doing so will cause them to become soulbound.\nSell Price:" }
entries[41092] = { ["name"] = "Glyph of Double Jeopardy", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nJudging a target increases the damage of your next Judgment by 20%, but only if used on a different second target.\nSell Price:" }
entries[41093] = { ["name"] = "Hyperspeed Accelerators", ["text"] = "Requires Engineering (375)\nUse: Increases your haste by 240 for 12 sec. (1 Min Cooldown)\nSell Price:" }
entries[41094] = { ["name"] = "Glyph of Devotion Aura", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nDevotion Aura no longer affects party or raid members, but the cooldown is reduced by 60 sec.\nSell Price:" }
entries[41095] = { ["name"] = "Glyph of Holy Wrath", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Holy Wrath now also stuns Elementals, Dragonkin, and Aberrations.\nSell Price:" }
entries[41096] = { ["name"] = "Glyph of Divine Protection", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nReduces the magical damage reduction of your Divine Protection to 20% but adds 20% physical damage reduction.\nSell Price:" }
entries[41097] = { ["name"] = "Glyph of Templar's Verdict", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou take 10% less damage for 6 sec after dealing damage with Templar's Verdict or Exorcism.\nSell Price:" }
entries[41098] = { ["name"] = "Glyph of Avenging Wrath", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nWhile Avenging Wrath is active, you are healed for 1% of your maximum health every 2 sec.\nSell Price:" }
entries[41099] = { ["name"] = "Glyph of Consecration", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou can now target Consecration anywhere within 25 yards.\nSell Price:" }
entries[41100] = { ["name"] = "Glyph of the Luminous Charger", ["text"] = "Minor Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Paladin class mounts glow with holy light.\nSell Price:" }
entries[41101] = { ["name"] = "Glyph of Focused Shield", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Avenger's Shield hits 2 fewer targets, but for 30% more damage.\nSell Price:" }
entries[41102] = { ["name"] = "Glyph of Burden of Guilt", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Judgment hits fill your target with doubt and remorse, reducing movement speed by 50% for 2 sec.\nSell Price:" }
entries[41103] = { ["name"] = "Glyph of Blinding Light", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Blinding Light now knocks down targets for 3 sec instead of Blinding them.\nSell Price:" }
entries[41104] = { ["name"] = "Glyph of Final Wrath", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Holy Wrath does an additional 50% damage to targets with less than 20% health.\nSell Price:" }
entries[41105] = { ["name"] = "Glyph of Word of Glory", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases your damage by 3% per Holy Power spent after you cast Word of Glory or Eternal Flame on a friendly target. Lasts 6 sec.\nSell Price:" }
entries[41106] = { ["name"] = "Glyph of Illumination", ["text"] = "Classes: Paladin\nRequires Level 25\nUse:\nYour Holy Shock criticals grant 1% mana return, but Meditation returns 10% less mana.\nSell Price:" }
entries[41107] = { ["name"] = "Glyph of Harsh Words", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYour Word of Glory can now also be used on enemy targets, causing Holy damage approximately equal to the amount it would have healed.\n\nDoes not work with Eternal Flame.\nSell Price:" }
entries[41108] = { ["name"] = "Glyph of Divinity", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nIncreases the cooldown of your Lay on Hands by 2 min but causes it to give you 10% of your maximum mana.\nSell Price:" }
entries[41109] = { ["name"] = "Glyph of Light of Dawn", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nLight of Dawn affects 2 fewer targets, but heals each target for 25% more.\nSell Price:" }
entries[41110] = { ["name"] = "Glyph of Blessed Life", ["text"] = "Major Glyph\nClasses: Paladin\nRequires Level 25\nUse: Permanently teaches you this glyph.\n\nYou have a 50% chance to gain a charge of Holy Power whenever you are affected by a Stun, Fear or Immobilize effect.\n\nThis effect cannot occur more than once every 20 sec. (Proc chance: 50%, 20s cooldown)\nSell Price:" }
entries[41111] = { ["name"] = "Flexweave Underlay", ["text"] = "Requires Engineering (375)\nUse: Permanently attaches a flexweave underlay to a cloak, allowing you to turn the cloak into a parachute and fall slowly for 30 sec.\n\nThe cloak can only be used once a minute and requires an Engineering skill of at least 350.\nSell Price:" }
entries[41112] = { ["name"] = "Mechanized Snow Goggles", ["text"] = "Binds when equipped\nHead Cloth\n581 Armor\n<Random enchantment>\nDurability 85 / 85\nRequires Engineering (400)\nEquip: Protected from the cold. Your Frost resistance is increased by 20.\nSell Price:" }
entries[41113] = { ["name"] = "Saronite Bulwark", ["text"] = "Binds when equipped\nOff Hand Shield\n5851 Armor\n+25 Strength\n+66 Stamina\n+ 31 Dodge\nDurability 65 / 65\nRequires Level 77\nSell Price:" }
entries[41114] = { ["name"] = "Tempered Saronite Gauntlets", ["text"] = "Binds when equipped\nHands Plate\n1361 Armor\n+28 Strength\n+55 Stamina\n+ 66 Dodge\nDurability 45 / 45\nRequires Level 78\nSell Price:" }
entries[41115] = { ["name"] = "Ragemane's Flipper", ["text"] = "Quest Item\nUnique\n\"Smelly and decomposed.\"" }
entries[41116] = { ["name"] = "Tempered Saronite Bracers", ["text"] = "Binds when equipped\nWrist Plate\n923 Armor\n+27 Strength\n+30 Stamina\n+ 48 Dodge\nDurability 45 / 45\nRequires Level 77\nSell Price:" }
entries[41117] = { ["name"] = "Saronite Protector", ["text"] = "Binds when equipped\nOff Hand Shield\n4890 Armor\n+26 Stamina\n+41 Intellect\n+ 23 Critical Strike\nDurability 65 / 65\nRequires Level 73\nSell Price:" }
entries[41118] = { ["name"] = "Nitro Boosts", ["text"] = "Requires Engineering (375)\nUse: Permanently attaches overpowered nitro boosts to your belt, allowing you to greatly increase run speed for 5 sec. They rarely explode violently, so don't worry about that.\n\nThe nitro boosts can only be activated every 3 minutes and require an Engineering skill of at least 400.\nSell Price:" }
entries[41119] = { ["name"] = "Saronite Bomb", ["text"] = "Requires Engineering (350)\nUse: Inflicts 1325 Fire damage to targets in a 10 yard radius. This explosive is powerful enough to cause moderate siege damage. (1 Min Cooldown)\nSell Price:" }
entries[41120] = { ["name"] = "Plans: Reinforced Cobalt Legplates", ["text"] = "Binds when picked up\nRequires Blacksmithing (375)\nUse: Teaches you how to make Reinforced Cobalt Legplates\nSell Price:\nReinforced Cobalt Legplates\nBinds when equipped\nLegs Plate\n1358 Armor\n+48 Strength\n+63 Stamina\n+ 31 Critical Strike\n+ 41 PvP Resilience\nDurability 85 / 85\nRequires Level 76\nSell Price:\nRequires Cobalt Bar (8), Crystallized Water (2)" }
entries[41121] = { ["name"] = "Gnomish Lightning Generator", ["text"] = "Binds when picked up\nTrinket\n+ 84 Critical Strike\nRequires Engineering (425)\nUse: Generates a bolt of lightning to strike an enemy for 1953 Nature damage. This entire device is made of metal.... (1 Min Cooldown)\n\"It's safe!\"\nSell Price:" }
entries[41122] = { ["name"] = "Plans: Reinforced Cobalt Chestpiece", ["text"] = "Binds when picked up\nRequires Blacksmithing (375)\nUse: Teaches you how to make a Reinforced Cobalt Chestpiece\nSell Price:\nReinforced Cobalt Chestpiece\nBinds when equipped\nChest Plate\n1606 Armor\n+47 Strength\n+64 Stamina\n+ 38 Critical Strike\n+ 43 PvP Resilience\nDurability 115 / 115\nRequires Level 77\nSell Price:\nRequires Cobalt Bar (8), Crystallized Water (2)" }
entries[41123] = { ["name"] = "Plans: Reinforced Cobalt Helm", ["text"] = "Binds when picked up\nRequires Blacksmithing (375)\nUse: Teaches you how to make Reinforced Cobalt Helm\nSell Price:\nReinforced Cobalt Helm\nBinds when equipped\nHead Plate\n1217 Armor\n+40 Strength\n+60 Stamina\n+ 40 Critical Strike\n+ 40 PvP Resilience\nDurability 70 / 70\nRequires Level 75\nSell Price:\nRequires Cobalt Bar (8), Crystallized Water (2)" }
entries[41124] = { ["name"] = "Plans: Reinforced Cobalt Shoulders", ["text"] = "Binds when picked up\nRequires Blacksmithing (375)\nUse: Teaches you how to make Reinforced Cobalt Shoulders\nSell Price:\nReinforced Cobalt Shoulders\nBinds when equipped\nShoulder Plate\n1042 Armor\n+28 Strength\n+42 Stamina\n+ 27 Critical Strike\n+ 27 PvP Resilience\nDurability 70 / 70\nRequires Level 73\nSell Price:\nRequires Cobalt Bar (8), Crystallized Water (2)" }
