entries[41131] = { ["name"] = "Rageclaw Fire Extinguisher", ["text"] = "Quest Item\nUnique\nUse: Use near burning Rageclaw wolvar huts to extinguish the fires!\n\"It looks like an ordinary bottle of water.\"" }
